config.initialContent:
job "example" {
  type = "service"

  group "app" {
    count = 1

    task "server" {
      driver = "docker"

      config {
        image = "nginx:alpine"
      }

      resources {
        cpu    = 100
        memory = 128
      }
    }
  }
}

